1	import { lazy, Suspense, useEffect } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	import { supabase } from "@/integrations/supabase/client";
14	
15	// Eager imports — core pages users navigate between constantly (no Suspense flash)
16	import Index from "./pages/Index";
17	import Auth from "./pages/Auth";
18	import Settings from "./pages/Settings";
19	import Profile from "./pages/Profile";
20	import Billing from "./pages/Billing";
21	import Team from "./pages/Team";
22	import Tasks from "./pages/Tasks";
23	import Activity from "./pages/Activity";
24	
25	// Sidebar-accessible pages — eager to avoid flash on click
26	import Changelog from "./pages/Changelog";
27	import RequestFeature from "./pages/RequestFeature";
28	
29	// Lazy imports — infrequent or large pages
30	const Admin = lazy(() => import("./pages/Admin"));
31	const NotFound = lazy(() => import("./pages/NotFound"));
32	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
33	const BookDemo = lazy(() => import("./pages/BookDemo"));
34	const Apply = lazy(() => import("./pages/Apply"));
35	const CareerPage = lazy(() => import("./pages/CareerPage"));
36	const CareerSettings = lazy(() => import("./pages/CareerSettings"));
37	const LandingPage = lazy(() => import("@/components/LandingPage"));
38	const SharedPortal = lazy(() => import("./pages/SharedPortal"));
39	
40	const queryClient = new QueryClient({
41	  defaultOptions: {
42	    queries: {
43	      staleTime: 5 * 60 * 1000,
44	      gcTime: 10 * 60 * 1000,
45	      refetchOnWindowFocus: false,
46	      refetchOnMount: false,
47	      retry: 1,
48	    },
49	  },
50	});
51	
52	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
53	const PageLoader = () => (
54	  <div className="flex h-svh w-full overflow-hidden">
55	    {/* Sidebar skeleton — matches sidebar width */}
56	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
57	      <div className="px-4 py-4">
58	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
59	      </div>
60	      <div className="border-t border-border" />
61	      <div className="p-3 space-y-2">
62	        {[1, 2, 3, 4].map((i) => (
63	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
64	        ))}
65	      </div>
66	    </div>
67	    {/* Content area skeleton */}
68	    <div className="flex-1 flex flex-col min-w-0">
69	      {/* Header skeleton */}
70	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
71	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
72	        <div className="flex items-center gap-3">
73	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
74	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
75	        </div>
76	      </div>
77	      {/* Body skeleton */}
78	      <div className="flex-1 overflow-y-auto p-6">
79	        <div className="max-w-5xl mx-auto space-y-4">
80	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
81	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
82	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
83	            {[1, 2, 3, 4].map((i) => (
84	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
85	            ))}
86	          </div>
87	        </div>
88	      </div>
89	    </div>
90	  </div>
91	);
92	
93	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
94	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
95	  const { isAdmin, loading } = useAuth();
96	
97	  // Don't block rendering while loading — only gate when we know maintenance is on
98	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
99	  return <>{children}</>;
100	};
101	
102	const RootRoute = () => {
103	  const { user, loading } = useAuth();
104	  if (loading) return <PageLoader />;
105	  return user ? <Index /> : <LandingPage />;
106	};
107	
108	/** Silently prefetches sidebar-linked pages so they open instantly on first click */
109	const DataPrefetcher = () => {
110	  const { user } = useAuth();
111	  const qc = useQueryClient();
112	
113	  useEffect(() => {
114	    // Prefetch public data that doesn't require auth
115	    qc.prefetchQuery({
116	      queryKey: ["changelog_public"],
117	      queryFn: async () => {
118	        const { data } = await (supabase as any)
119	          .from("changelog")
120	          .select("id, version, title, description, category, published_at")
121	          .eq("status", "published")
122	          .order("published_at", { ascending: false });
123	        return data ?? [];
124	      },
125	      staleTime: 5 * 60 * 1000,
126	    });
127	    qc.prefetchQuery({
128	      queryKey: ["feature_requests"],
129	      queryFn: async () => {
130	        const { data } = await (supabase as any)
131	          .from("feature_requests")
132	          .select("*")
133	          .order("created_at", { ascending: false });
134	        return data ?? [];
135	      },
136	      staleTime: 5 * 60 * 1000,
137	    });
138	  }, []);
139	
140	  useEffect(() => {
141	    if (!user) return;
142	    qc.prefetchQuery({
143	      queryKey: ["my_feature_votes"],
144	      queryFn: async () => {
145	        const { data } = await (supabase as any)
146	          .from("feature_request_votes")
147	          .select("feature_request_id")
148	          .eq("user_id", user.id);
149	        return (data ?? []).map((v: any) => v.feature_request_id);
150	      },
151	      staleTime: 5 * 60 * 1000,
152	    });
153	  }, [user?.id]);
154	
155	  return null;
156	};
157	
158	const App = () => (
159	  <QueryClientProvider client={queryClient}>
160	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
161	      <AuthProvider>
162	        <DataPrefetcher />
163	        <TooltipProvider>
164	          <Sonner />
165	          <BrowserRouter>
166	            <SeoHead />
167	            <Suspense fallback={<PageLoader />}>
168	              <Routes>
169	                {/* Public pages — outside MaintenanceGate so candidates/guests can always access */}
170	                <Route path="/apply/:jobId" element={<Apply />} />
171	                <Route path="/careers/:slug" element={<CareerPage />} />
172	                <Route path="/shared/:token" element={<SharedPortal />} />
173	                <Route path="*" element={
174	                  <MaintenanceGate>
175	                    <Routes>
176	                      <Route path="/auth" element={<Auth />} />
177	                      <Route path="/" element={<RootRoute />} />
178	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
179	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
180	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
181	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
182	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
183	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
184	                      <Route path="/activity" element={<ProtectedRoute><Activity /></ProtectedRoute>} />
185	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
186	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
187	                      <Route path="/book-demo" element={<BookDemo />} />
188	                      <Route path="/request-feature" element={<RequestFeature />} />
189	                      <Route path="/changelog" element={<Changelog />} />
190	                      <Route path="/payment/callback" element={<PaymentCallback />} />
191	                      <Route path="*" element={<NotFound />} />
192	                    </Routes>
193	                  </MaintenanceGate>
194	                } />
195	              </Routes>
196	            </Suspense>
197	            <ChatWidget />
198	          </BrowserRouter>
199	        </TooltipProvider>
200	      </AuthProvider>
201	    </ThemeProvider>
202	  </QueryClientProvider>
203	);
204	
205	export default App;
206	
