9	
10	const Auth = () => {
11	  const { user, loading } = useAuth();
12	  const navigate = useNavigate();
13	  const [searchParams] = useSearchParams();
14	  const inviteToken = searchParams.get("invite");
15	
16	  const acceptInvite = useCallback(async (token: string) => {
17	    try {
18	      const { data: { session } } = await supabase.auth.getSession();
19	      if (!session?.access_token) return;
20	
21	      const res = await fetch(
22	        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/accept-team-invite`,
23	        {
24	          method: "POST",
25	          headers: {
26	            "Content-Type": "application/json",
27	            "Authorization": `Bearer ${session.access_token}`,
28	            "apikey": import.meta.env.VITE_SUPABASE_ANON_KEY,
29	          },
30	          body: JSON.stringify({ token }),
31	        }
32	      );
33	
34	      const json = await res.json();
35	      if (res.ok && json.success) {
36	        toast.success(`Joined team: ${json.team_name ?? "Team"}`);
37	        navigate("/team", { replace: true });
38	        return;
39	      }
40	    } catch {
41	      // Silently fail — user can accept invite manually later
42	    }
43	    navigate("/", { replace: true });
44	  }, [navigate]);
45	
46	  useEffect(() => {
47	    if (!loading && user) {
48	      if (inviteToken) {
49	        acceptInvite(inviteToken);
50	      } else {
51	        navigate("/", { replace: true });
52	      }
53	    }
54	  }, [user, loading, navigate, inviteToken, acceptInvite]);
55	
56	  return (
57	    <div className="flex min-h-screen items-center justify-center bg-background px-4">
58	      <Card className="w-full max-w-md shadow-lg border-border/50">
59	        <CardHeader className="text-center space-y-2">
60	          <div className="flex items-center justify-center gap-2 mb-2">
61	            <Zap className="h-7 w-7 text-primary" />
62	            <span className="text-xl font-bold text-foreground tracking-tight">Rankora</span>
63	          </div>
64	          <CardTitle className="text-2xl">
65	            {inviteToken ? "Join Your Team" : "Welcome"}
66	          </CardTitle>
67	          <CardDescription>
68	            {inviteToken
69	              ? "Sign in or create an account to accept the team invitation"
70	              : "Sign in to rank candidates instantly"}
71	          </CardDescription>
72	        </CardHeader>
73	        <CardContent>
74	          <AuthForm onSuccess={() => {
75	            if (inviteToken) {
76	              acceptInvite(inviteToken);
77	            } else {
78	              navigate("/", { replace: true });
79	            }
80	          }} />
81	        </CardContent>
82	      </Card>
83	    </div>
84	  );
85	};
86	
87	export default Auth;
