1	import React, { useState, useCallback, useEffect, useMemo } from "react";
2	import { useSearchParams, useLocation } from "react-router-dom";
3	import { useQuery, useQueryClient } from "@tanstack/react-query";
4	import { useAuth } from "@/hooks/useAuth";
5	import { supabase } from "@/integrations/supabase/client";
6	import AppHeader from "@/components/AppHeader";
7	import AuthDialog from "@/components/AuthDialog";
8	import JobSidebar from "@/components/JobSidebar";
