19	export interface PastJob {
20	  id: string;
21	  title: string | null;
22	  job_description: string;
23	  status: string;
24	  created_at: string;
25	  resume_count: number;
26	  jd_analysis_json: any;
27	  dynamic_weights_json: Record<string, number> | null;
