31	export interface Result {
32	  id: string;
33	  resume_id: string;
34	  overall_score: number;
35	  missing_skills: string[];
36	  summary: string | null;
37	  interview_questions: any;
38	  filename: string;
39	  file_path: string | null;
40	  candidate_name: string | null;
41	  candidate_email?: string | null;
42	  candidate_phone?: string | null;
43	  candidate_location?: string | null;
44	  // Dynamic scoring fields
45	  hard_fit?: boolean;
46	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
47	  confidence?: number;
48	  strengths_json?: string[];
49	  gaps_json?: string[];
50	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
51	  matched_must_haves?: string[];
52	  missing_must_haves?: string[];
53	  scoring_version?: string;
54	  pending?: boolean;
55	  parsed_json?: any;
