65	
66	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
67	
68	const Index = () => {
69	  const { user, profile } = useAuth();
70	  const [searchParams, setSearchParams] = useSearchParams();
71	  const location = useLocation();
72	
73	  const queryClient = useQueryClient();
74	
75	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
76	    queryKey: ["pastJobs", user?.id],
77	    queryFn: async () => {
78	      const { data: jobs } = await supabase
79	        .from("jobs")
80	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
81	        .eq("user_id", user!.id)
82	        .order("created_at", { ascending: false })
83	        .limit(50);
84	      if (!jobs) return [];
85	      return jobs.map((j: any) => ({
86	        id: j.id,
87	        title: j.title,
88	        job_description: j.job_description,
89	        status: j.status,
90	        created_at: j.created_at,
91	        resume_count: j.resumes?.[0]?.count ?? 0,
92	        jd_analysis_json: j.jd_analysis_json,
93	        dynamic_weights_json: j.dynamic_weights_json,
94	        inbox_email: j.inbox_email ?? null,
95	      })) as PastJob[];
96	    },
97	    enabled: !!user,
98	    staleTime: 2 * 60 * 1000,
99	  });
100	
101	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
102	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
103	  const [results, setResults] = useState<Result[]>([]);
104	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
105	  const [authOpen, setAuthOpen] = useState(false);
106	
107	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
108	
109	  // Sync view with route path
110	  useEffect(() => {
111	    if (location.pathname === "/jobs") {
112	      setView("my-jobs");
113	      setSelectedJobId(null);
114	    }
115	  }, [location.pathname]);
116	
117	  // Handle URL params for deep linking
118	  useEffect(() => {
119	    const jobParam = searchParams.get("job");
120	    const newParam = searchParams.get("new");
121	
122	    if (jobParam && user) {
123	      loadJobData(jobParam);
124	      setSearchParams({}, { replace: true });
125	    } else if (newParam && user) {
126	      handleNewJob();
127	      setSearchParams({}, { replace: true });
128	    }
129	    // eslint-disable-next-line react-hooks/exhaustive-deps
130	  }, [searchParams, user]);
131	
132	  const loadJobData = async (jobId: string) => {
133	    setSelectedJobId(jobId);
134	    setView("job-detail");
135	    try {
136	      // Single query for all resume data (was 2 separate queries)
137	      const { data: allResumes } = await supabase
138	        .from("resumes")
139	        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
140	        .eq("job_id", jobId)
141	        .order("created_at", { ascending: false });
142	
143	      const resumeData = allResumes ?? [];
144	      setExistingResumes(resumeData.map((r) => ({
145	        id: r.id, filename: r.filename, file_path: r.file_path,
146	        candidate_name: r.candidate_name, created_at: r.created_at,
147	      })));
148	
149	      if (resumeData.length === 0) {
150	        setResults([]);
151	        return;
152	      }
153	
154	      const resumeIds = resumeData.map((r) => r.id);
155	      const { data: resultData } = await supabase
156	        .from("results")
157	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
158	        .in("resume_id", resumeIds);
159	
160	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
161	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
162	        const resume = resumeMap.get(r.resume_id);
163	        const parsed = resume?.parsed_json as any;
164	        return {
165	          ...r,
166	          overall_score: r.overall_score ?? 0,
167	          missing_skills: r.missing_skills ?? [],
168	          filename: resume?.filename ?? "Unknown",
169	          file_path: resume?.file_path ?? null,
170	          candidate_name: resume?.candidate_name ?? null,
171	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
172	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
173	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
174	          parsed_json: resume?.parsed_json ?? null,
