19	function parseCSVLine(line: string): string[] {
20	  const result: string[] = [];
21	  let current = "";
22	  let inQuotes = false;
23	  for (const char of line) {
24	    if (char === '"') {
25	      inQuotes = !inQuotes;
26	    } else if (char === "," && !inQuotes) {
27	      result.push(current.trim());
28	      current = "";
29	    } else {
30	      current += char;
31	    }
32	  }
33	  result.push(current.trim());
34	  return result;
35	}
