37	function parseCSV(text: string): { headers: string[]; rows: string[][] } {
38	  const lines = text.split("\n").filter((l) => l.trim());
39	  if (lines.length === 0) return { headers: [], rows: [] };
40	  const headers = parseCSVLine(lines[0]);
41	  const rows = lines.slice(1).map(parseCSVLine);
42	  return { headers, rows };
43	}
